package com.bank.pbench;

import java.util.*;
import java.util.logging.*;
import java.util.stream.LongStream;

public class BenchmarkDemo {
    private static final Logger log = Logger.getLogger("PBench");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        BenchmarkService service = new BenchmarkService();
        List<Long> small = LongStream.rangeClosed(1, 10).boxed().toList();
        List<Long> large = LongStream.rangeClosed(1, 10_000_000).boxed().toList();

        service.compare(log, "n=10", small);
        service.compare(log, "n=10,000,000", large);
    }
}

// ─── Would be in service/BenchmarkService.java ───
class BenchmarkService {
    void compare(Logger log, String label, List<Long> data) {
        long seq = time(() -> data.stream().mapToLong(Long::longValue).sum());
        long par = time(() -> data.parallelStream().mapToLong(Long::longValue).sum());
        log.info(() -> label + " → sequential=" + seq + "ns  parallel=" + par + "ns");
    }
    // NOTE: indicative only — real benchmarking needs JMH (warm-up, dead-code elimination)
    private long time(Runnable r) {
        long start = System.nanoTime();
        r.run();
        return System.nanoTime() - start;
    }
}
